mapper.select:
SELECT user_id as cd, SUM(money) AS amount FROM `finance_bill` where TYPE=2
and DATE_FORMAT(bill_date, '%Y-%m') >= #{query.startMonth}
and DATE_FORMAT(bill_date, '%Y-%m') <= #{query.endMonth}
GROUP BY user_id

SELECT m.userName as name, n.billDate as date, n.amount FROM `sys_user` m INNER JOIN ( SELECT o.user_id,o.billDate,SUM(o.money) AS amount FROM ( SELECT user_id, DATE_FORMAT(bill_date, '%Y-%m') AS billDate, money FROM `finance_bill` WHERE TYPE=2
and DATE_FORMAT(bill_date, '%Y-%m') >= #{query.startMonth}
and DATE_FORMAT(bill_date, '%Y-%m') <= #{query.endMonth}
)o GROUP BY o.user_id,o.billDate )n ON m.id=n.user_id

select category_id as cd, sum(money) as amount from `finance_bill` where type=2
and DATE_FORMAT(bill_date, '%Y-%m') >= #{query.startMonth}
and DATE_FORMAT(bill_date, '%Y-%m') <= #{query.endMonth}
group by category_id
